SELECT expected.table_name, expected.id_column,
  CASE WHEN t.TABLE_NAME IS NULL THEN 'THIEU_BANG'
       WHEN t.TABLE_TYPE<>'BASE TABLE' THEN 'BANG_LA_VIEW_KHONG_DUOC_ALTER'
       WHEN c.COLUMN_NAME IS NULL THEN 'THIEU_ID_CAN_XU_LY_RIENG' ELSE 'OK' END AS trang_thai
FROM (
  SELECT 'tbwtmcy' AS table_name, 'Tbwtmcy_id' AS id_column
  UNION ALL SELECT 'tltdqzy', 'Tltdqzy_id'
  UNION ALL SELECT 't7lkybu', 'T7lkybu_id'
  UNION ALL SELECT 'tm9ogbr', 'Tm9ogbr_id'
  UNION ALL SELECT 'taj5r8p', 'Taj5r8p_id'
