  UNION ALL SELECT 'ta7iu8z', 'Ta7iu8z_id'
  UNION ALL SELECT 'thnrej4', 'Thnrej4_id'
  UNION ALL SELECT 'txrmvof', 'Txrmvof_id'
  UNION ALL SELECT 'tbi7das', 'Tbi7das_id'
  UNION ALL SELECT 'tlcpgvq', 'Tlcpgvq_id'
  UNION ALL SELECT 'tiljgp2', 'Tiljgp2_id'
  UNION ALL SELECT 'tm5psbg', 'Tm5psbg_id'
  UNION ALL SELECT 'tfor3sb', 'Tfor3sb_id'
  UNION ALL SELECT 'tcjrbf5', 'Tcjrbf5_id'
  UNION ALL SELECT 'tmubtp4', 'Tmubtp4_id'
) AS expected
LEFT JOIN information_schema.TABLES t ON t.TABLE_SCHEMA=DATABASE() AND t.TABLE_NAME=expected.table_name
LEFT JOIN information_schema.COLUMNS c ON c.TABLE_SCHEMA=DATABASE() AND c.TABLE_NAME=expected.table_name AND c.COLUMN_NAME=expected.id_column
WHERE t.TABLE_NAME IS NULL OR t.TABLE_TYPE<>'BASE TABLE' OR c.COLUMN_NAME IS NULL;

